function markerBegin(name: string) {
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	if (typeof engine == "object" && typeof (engine as any).call == "function") {
		engine.call("profileBegin", name);
	}
}

function markerEnd() {
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	if (typeof engine == "object" && typeof (engine as any).call == "function") {
		engine.call("profileEnd", 0);
	}
}

export class profileScope {
	private m_startTime = 0;
	private m_name: string;
	constructor(name: string) {
		this.m_startTime = Date.now();
		this.m_name = name;
		console.log(`Begin Scope: ${this.m_name}`);
		markerBegin(name);
	}

	end() {
		const duration = Date.now() - this.m_startTime;
		console.log(`Scope end: ${this.m_name}, ${duration} ms`);
		markerEnd();
	}
}

export function profileFunction<T = unknown>(name: string, func: () => T): T {
	const scope = new profileScope(name);
	const ret: T = func();
	scope.end();
	return ret;
}
